CREATE FUNCTION `art_cdp_formatear_string`(xstr varchar(255)) RETURNS varchar(255) CHARSET latin1 COLLATE latin1_swedish_ci
    DETERMINISTIC
begin
	set xstr = replace(xstr, ' ', '');
	set xstr = replace(xstr, '(', '');
    set xstr = replace(xstr, ')', '');
    set xstr = replace(xstr, '/', '');
    set xstr = replace(xstr, '.', '');
    set xstr = replace(xstr, '-', '');
	set xstr = replace(xstr, '*', '');
	set xstr = replace(xstr, '\"', '');
	set xstr = replace(xstr, ',', '');
	set xstr = replace(xstr, '\'', '');
	set xstr = replace(xstr, '=>', '');
	set xstr = replace(xstr, ':', '');
	set xstr = replace(xstr, ';', '');
	set xstr = replace(xstr, '>', '');
	set xstr = replace(xstr, '<', '');
	set xstr = replace(xstr, '=', '');
	set xstr = replace(xstr, '+', '');
	set xstr = replace(xstr, '-', '');
    set xstr = replace(xstr, '}', '');
    return xstr;
end ;;
DELIMITER ;
