CREATE FUNCTION `equiv_tieneEquiv`(pIdArticulo int) RETURNS bit(1)
    DETERMINISTIC
BEGIN
	DECLARE vTieneEquiv bit;
	DECLARE vEquiv int;

	SELECT equiv INTO vEquiv
	FROM articulos
	WHERE articulos.idArticulo = pIdArticulo;

	SELECT
		CASE
			WHEN COUNT(*) > 1 THEN 1
			ELSE 0
		END INTO vTieneEquiv
	FROM articulos
	WHERE articulos.equiv = vEquiv;
	RETURN vTieneEquiv;
END ;;
DELIMITER ;
