CREATE PROCEDURE `agregar_faltantes`(
	xidArticulo int,
	xcodArt varchar(20),
	xuniCpr float,
	xcantidad float,
	xidcliente int,
	xusuario varchar(5),
	xhost varchar(50))
BEGIN
	DECLARE vMensaje VARCHAR(200);
	DECLARE vCantReg INT;
	DECLARE vProxID INT;
	DECLARE EXIT HANDLER FOR SQLEXCEPTION
	BEGIN
		ROLLBACK;
		GET DIAGNOSTICS CONDITION 1 vMensaje = MESSAGE_TEXT;
	END;
	
	START TRANSACTION;
	
	-- Verifico si el artÃ­culo existe
	SELECT
		COUNT(*)
	INTO
		vCantReg
	FROM
		faltantes
	WHERE
		idArticulo = xidArticulo AND
                procesado = 0 AND
		fecBaja IS NULL;
	
	IF vCantReg = 0 THEN
		SELECT
			IFNULL(MAX(idFaltante), 0) + 1
		INTO
			vProxID
		FROM
			faltantes;
	
			idFaltante,
			idArticulo,
			codArt,
			uniCpr,
			cantidad,
			procesado,
			idCliente,
			usuAlta,
			fecAlta,
			idHostAlta)
		VALUES (
			vProxID,
			xidArticulo,
			xcodArt,
			xuniCpr,
			xcantidad,
			0,
			CASE WHEN xidcliente = 0 THEN NULL ELSE xidcliente END,
			xusuario,
			CURRENT_TIMESTAMP,
			xhost);
	ELSE
		UPDATE
			faltantes
		SET
			cantidad = cantidad + xcantidad
		WHERE
			idArticulo = xidArticulo;
	END IF;
	
	COMMIT;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `agregar_menu` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb3 */ ;
/*!50003 SET character_set_results = utf8mb3 */ ;
/*!50003 SET collation_connection  = utf8mb3_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `agregar_menu`(
	  xCodMenu	varchar(20),
	  xNombre	varchar(60),
	  xProcedim	varchar(60),
	  xIsChild	bit(1),
	  xEnlace	int(11),
	  xacc_key	varchar(30),
	  xorden	int
	)
BEGIN
		/**
	     * Agrega un menú al sistema si no existe.
	    */
		DECLARE vProxId int;
	    DECLARE vExisteMenu bit;
	    DECLARE vIdAcceso int;
	    DECLARE mensaje text;

	    DECLARE EXIT HANDLER FOR SQLEXCEPTION
	    BEGIN
	    	ROLLBACK;
	        GET DIAGNOSTICS CONDITION 1 mensaje = MESSAGE_TEXT;
	        SELECT mensaje;
	    END;

	    SET vExisteMenu = (
	    	SELECT
	        	CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END
	        FROM
	        	menues
	        WHERE
	        	menues.CodMenu = xCodMenu);

	    IF vExisteMenu = 0 THEN
	    	START TRANSACTION;

			SET vProxId = (
	        	SELECT
	            	CASE WHEN MAX(idMenue) IS NULL THEN 1 ELSE MAX(idMenue) + 1 END
	            FROM
	            	menues);

	          idMenue,
	          CodMenu,
	          Nombre,
	          Procedim,
	          IsChild,
	          Enlace,
	          acc_key,
	          orden,
	          usuAlta,
	          fecAlta,
	          idHostAlta)
	        VALUES (
	          vProxId,
	          xCodMenu,
	          xNombre,
	          xProcedim,
	          xIsChild,
	          xEnlace,
	          xacc_key,
	          xorden,
	          'SUPER',
	          current_timestamp,
	          'SISTEMA');

	    	/* Asocio el menú al usuario SUPER */
	        SET vIdAcceso = (
	        	SELECT
	            	CASE WHEN MAX(idAcceso) IS NULL THEN 1 ELSE MAX(idAcceso) + 1 END
	            FROM
	            	accesos);

	        	idAcceso,
	            idUsuario,
	            idMenue
	        ) VALUES (
	        	vIdAcceso,
	            1,
				vProxId);

			COMMIT;
	    END IF;
	END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
