CREATE PROCEDURE `artcat_addFamilia`(

	pUsuario VARCHAR(5),

	pHostName VARCHAR(50)

)
BEGIN

	SELECT

		CASE WHEN MAX(idFamilia) IS NULL THEN 0

		ELSE idFamilia END

	INTO

		@idFamilia

	FROM

		familias;

	


		idFamilia,

		descripcio,

		usuAlta,

		fecAlta,

		idHostAlta)

			SELECT 

				(@idFamilia := @idFamilia + 1) AS idFamilia,

				familia AS descripcio,

				pUsuario AS usuAlta,

				CURRENT_TIMESTAMP AS fecAlta,

				pHostName AS idHostAlta

			FROM 

				tmp_artcat 

			WHERE 

				idArticulo = 0 AND

				familia NOT IN (

					SELECT

						descripcio

					FROM

						familias)

			GROUP BY

				familia;

END ;;
DELIMITER ;
