CREATE PROCEDURE `articulos_getByCod`(pCodArt varchar(20))
BEGIN
	SELECT
		*
   	FROM
    		articulos
	WHERE
    		articulos.codArt = pCodArt AND
		articulos.fecBaja IS NULL;
END ;;
