CREATE PROCEDURE `articulos_insert`(
	p_idprov int, 
	p_idfamilia int, 
	p_idsubfam int, 
	p_idmarca int, 
	p_codart varchar(20), 
	p_descripcio varchar(200), 
	p_aliciva  decimal(10, 2), 
	p_tmon varchar(3), 
	p_prlistaext  decimal(10, 2), 
	p_cotizac  decimal(10, 2), 
	p_prlista  decimal(10, 2), 
	p_bonif1  decimal(10, 2), 
	p_bonif2  decimal(10, 2), 
	p_bonif3  decimal(10, 2), 
	p_bonif4  decimal(10, 2), 
	p_costorep  decimal(10, 2), 
	p_margenmax  decimal(10, 2), 
	p_margenmin  decimal(10, 2), 
	p_prventamax  decimal(10, 2), 
	p_prventamin  decimal(10, 2), 
	p_prfinalmax  decimal(10, 2), 
	p_prfinalmin  decimal(10, 2), 
    p_usarImpIn bit,
    p_porImpuIn decimal(5, 2),
    p_impImInMay decimal(20, 2),
    p_impImInMin decimal(20, 2),
	p_observ text, 
	p_habilitado bit,
	p_linkfoto varchar(100), 
	p_usualta varchar(5), 
	p_idhostalta varchar(50),
	p_esserv bit, 
	p_idunimed int, 
	p_codartpv varchar(45), 
	p_mostrador bit,
	p_llevastk bit,
    p_usarMonExt bit,
	p_promocion bit)
BEGIN
	

	DECLARE v_idarticulo int;

	
	SET v_idarticulo = (
		SELECT CASE
			WHEN MAX(idarticulo) IS NULL THEN 1
            ELSE MAX(idarticulo) + 1 END
		FROM articulos);

	
		idarticulo, 
		idprov, 
		idfamilia, 
		idsubfam, 
		idmarca, 
		codart, 
		descripcio,
		aliciva, 
		tmon, 
		prlistaext, 
		cotizac, 
		prlista, 
		bonif1, 
		bonif2, 
		bonif3,
		bonif4, 
		costorep, 
		margenmax, 
		margenmin, 
		prventamax, 
		prventamin, 
		prfinalmax,
		prfinalmin,
        usarImpuIn,
        porImpuIn,
        impImInMay,
        impImInMin,
		observ, 
		habilitado, 
		linkfoto, 
		usualta, 
		fecalta, 
		idhostalta,
		esserv, 
		idunimed, 
		codartpv, 
		mostrador,
		llevastk, 
		equiv,
        usarMonExt,
		promocion)
	VALUES (
		v_idarticulo, 
		p_idprov,  
		p_idfamilia, 
		p_idsubfam, 
		p_idmarca, 
		p_codart, 
		p_descripcio,
		p_aliciva, 
		p_tmon, 
		p_prlistaext, 
		p_cotizac, 
		p_prlista, 
		p_bonif1, 
		p_bonif2, 
		p_bonif3,
		p_bonif4, 
		p_costorep, 
		p_margenmax, 
		p_margenmin, 
		p_prventamax, 
		p_prventamin, 
		p_prfinalmax,
		p_prfinalmin,
        p_usarImpIn,
        p_porImpuIn,
        p_impImInMay,
        p_impImInMin,
		p_observ, 
		p_habilitado, 
		p_linkfoto, 
		p_usualta, 
		current_timestamp, 
		p_idhostalta,
		p_esserv, 
		p_idunimed, 
		p_codartpv, 
		p_mostrador,
		p_llevastk, 
		v_idarticulo,
        p_usarMonExt,
		p_promocion);

	
    CALL codiart_insert (v_idarticulo, p_codart, p_codart, 'CP', 1, 'CV');

	
		idarticulo, 
		idstkdep, 
		usualta, 
		fecalta, 
		idhostalta)
	VALUES (
		v_idarticulo, 
		1, 
		p_usualta, 
		current_timestamp, 
		p_idhostalta);

    SELECT v_idarticulo AS result;
END ;;
DELIMITER ;
