CREATE PROCEDURE `articulos_validarCodigo`(
	pCodArt varchar(20))
BEGIN
	SELECT
		CASE WHEN COUNT(*) > 0 THEN 1
			ELSE 0 END 'result'
	FROM
		articulos
	WHERE
		articulos.codArt = pCodArt AND
		articulos.fecBaja IS NULL;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
