CREATE PROCEDURE `art_cbios_getByArt`(
	pIdArticulo INT
)
BEGIN
	SELECT
		art_cbios.fecha,
		art_cbios.prAnt,
		art_cbios.prNuevo,
		art_cbios.porVar
	FROM
		art_cbios
	WHERE
		art_cbios.idArticulo = pIdArticulo
    ORDER BY art_cbios.fecha DESC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
