CREATE PROCEDURE `art_cbios_insert`(
	pIdArticulo INT,
	pPrAnt DOUBLE,
	pPrNuevo DOUBLE
)
BEGIN
	DECLARE vIdArtCbio INT;
	DECLARE vPorcentaje DOUBLE;

    IF pPrAnt <> 0 THEN
    	SET vPorcentaje = ROUND(((pPrNuevo - pPrAnt) * 100) / pPrAnt, 4);
    ELSE
        SET vPorcentaje = 0;
    END IF;

	IF vPorcentaje != 0 THEN		
		SELECT
			CASE 
				WHEN MAX(idArtCbios) IS NULL THEN 1 
					ELSE MAX(idArtCbios) + 1 END
			INTO vIdArtCbio
		FROM
			art_cbios;
					
			idArtCbios,
			idArticulo,
			fecha,
			prAnt,
			prNuevo,
			porVar)
		VALUES (
			vIdArtCbio,
			pIdArticulo,
			CURRENT_TIMESTAMP,
			pPrAnt,
			pPrNuevo,
			vPorcentaje
		);
	END IF;
END ;;
DELIMITER ;
