CREATE PROCEDURE `art_tempo_tienePend`(_idProv int)
begin
	declare cantReg int;
    declare resultado bit;
    set cantReg = (select count(*)
		from art_tempo
        where procesado = 0
			and idprov = _idProv);
	if cantReg > 0 then
		set resultado = 1;
	else
		set resultado = 0;
    end if;
    select resultado as result;
end ;;
DELIMITER ;
