CREATE PROCEDURE `art_upd_tempo_limpiar`(pIdProv int)
begin
	declare exit handler for sqlexception
    begin
		rollback;
        select 0 as result;
    end;
    delete from art_upd_tempo where idProv = pIdProv;
    commit;
    select 1 as result;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
