CREATE PROCEDURE `cheques_buscarND`(
	_nroCheque varchar(8),
    _idBanco int)
begin
	select *
    from cheques
    where cheques.chq_nro = _nroCheque
		and cheques.idBanco = _idBanco
        and cheques.estado != 'R';
end ;;
