/*!50003 SET character_set_results = cp850 */ ;
/*!50003 SET collation_connection  = cp850_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `clientes_getById`( _idCliente int)
BEGIN
	SELECT *
    FROM clientes
    WHERE idCliente = _idCliente;
END ;;
