CREATE PROCEDURE `faltantes_insert`(
	_idArticulo int,
    _idCliente int,
    _idVentasC int,
    _codArt varchar(20),
    _uniCpr double,
    _cantidad double,
    _procesado bit,
    _idOcCab int,
    _usuAlta varchar(5),
    _idHostAlta varchar(50))
begin
    declare _proxID int;
    set _proxID = (
	select
		case when max(idFaltante) is null then 1
		else max(idFaltante) + 1 end
	from faltantes);
		idFaltante,
	        idArticulo,
        	idCliente,
	        idVentasC,
        	codArt,
	        uniCpr,
        	cantidad,
	        procesado,
        	idOcCab,
	        usuAlta,
        	fecAlta,
	        idHostAlta)
	values (
		_proxID,
        	_idArticulo,
	        _idCliente,
        	_idVentasC,
	        _codArt,
        	_uniCpr,
	        _cantidad,
        	_procesado,
	        _idOcCab,
        	_usuAlta,
	        current_timestamp,
        	_idHostAlta);
end ;;
DELIMITER ;
