/*!50003 SET character_set_results = utf8mb3 */ ;
/*!50003 SET collation_connection  = utf8mb3_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `num_getNroCbte`(
	p_cbte varchar(3),
	p_ptoVta int,
	p_hostName varchar(50)
)
BEGIN
	DECLARE v_idNum int;
	DECLARE v_nroActual int;
	DECLARE v_rtoPrinter varchar(100);
	DECLARE v_cantCpias int;
	DECLARE v_hayNumerador bit;	
	DECLARE v_hayImpresora bit;
    DECLARE v_usaTicket bit;

	SET v_rtoPrinter = '';
	SET v_cantCpias = 0;
	SET v_idNum = 0;
	SET v_nroActual = 0;
	SET v_hayImpresora = 0;
	SET v_hayNumerador = 0;
    SET v_usaTicket = 0;

	SELECT 
		CASE 
			WHEN COUNT(*) > 0 THEN 1
			ELSE 0 END INTO v_hayNumerador
	FROM
		numerador n
	WHERE
		n.cbte = p_cbte AND
		n.ptoVta = p_ptoVta;

	IF v_hayNumerador = 1 THEN
		SELECT
			n.idNum,
			n.numActual + 1
		INTO
			v_idNum,
			v_nroActual
		FROM
			numerador n
		WHERE
			n.cbte = p_cbte AND
			n.ptoVta = p_ptoVta;
		
		SELECT
			CASE
				WHEN COUNT(*) > 0 THEN 1
				ELSE 0 END INTO v_hayImpresora
		FROM
			impresoras i
		WHERE
			i.hostName = p_hostName AND		
			i.idNum = v_idNum;
		
		IF v_hayImpresora = 1 THEN
			SELECT
				impresora,
				copias,
                usa_ticket
			INTO
				v_rtoPrinter,
				v_cantCpias,
                v_usaTicket
			FROM
				impresoras i
			WHERE
				i.hostName = p_hostName AND		
				i.idNum = v_idNum;
		END IF;
	END IF;
	SELECT
		v_idNum AS idNum,
		v_nroActual AS numActual,
		v_rtoPrinter AS impresora,
		v_cantCpias AS copias,
		v_hayNumerador AS hayNumerador,
		v_hayImpresora AS hayImpresora,
        v_usaTicket AS usa_ticket;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
