CREATE PROCEDURE `obtener_Ranking_BYC`()
BEGIN
	DECLARE total double;
	
	SET total = calcular_total_universo();
	SELECT
		codArt,
		cantidad,
		(cantidad * 100) / total AS porcentaje
	FROM temp_universo
	GROUP BY codArt
	ORDER BY (cantidad * 100) / total DESC;
END ;;
DELIMITER ;
