CREATE PROCEDURE `ofertas_getVigenteByArt`(_idArticulo int)
begin
	select *
    from ofertas
    where ofertas.idArticulo = _idArticulo
		and ofertas.fecVigDD <= current_timestamp
        and ofertas.fecVigHH >= current_timestamp;
end ;;
