CREATE PROCEDURE `pedext_getDescargados`()
begin
	select 
		pedext.idPedCab,
		pedext.idCliente,
		pedext.fecEmis,
		clientes.razSoc   
	from pedext
		inner join clientes on clientes.idCliente = pedext.idCliente
	where procesado = 0
	group by idPedCab;
end ;;
