    _observ text)
BEGIN
    IF _idArticulo <> 0 THEN
            idPedCab, idCliente, tipoSist, idArticulo, 
            fecEmis, codArt, cantidad, observ, procesado)
        VALUES (
            _idPedCab, _idCliente, _tipoSist, _idArticulo,
            _fecEmis, _codArt, _cantidad, _observ, 0);
    END IF;
END ;;
DELIMITER ;
