CREATE PROCEDURE `upd_ArtTempUpdate`(
    pidFamilia int,
    pidSubFam int,
    pidMarca int,
    pcodArt varchar(20),
    pcodArtPV varchar(20),
    pdescripcio varchar(200),
    palicIVA double,
    pprListaPV double,
    pbonif1 double,
    pbonif2 double,
    pbonif3 double,
    pbonif4 double,
    pcostoRep double,
    pmargenMay double,
    pmargenMin double,
    pprVentaMay double,
    pprVentaMin double,
    pprocesado bit)
begin
	update art_tempo
    set idFamilia = pidFamilia,
		idSubFam = pidSubFam,
        idMarca = pidMarca,
        codArt = pcodArt,
        descripcio = UPPER(pdescripcio),
        alicIVA = palicIVA,
        bonif1 = pbonif1,
        bonif2 = pbonif2,
        bonif3 = pbonif3,
        bonif4 = pbonif4,
        costoRep = pcostoRep,
        margenMay = pmargenMay,
        margenMin = pmargenMin,
        prVentaMay = pprVentaMay,
        prVentaMin = pprVentaMin,
        procesado = pprocesado
	where codArtPV = pcodArtPV
		and procesado = 0;
end ;;
DELIMITER ;
