CREATE PROCEDURE `vtadcp_getByCab`( _idVentasC int)
begin
	select vtadcp.*,
		planctas.codPlanCta,
	        planctas.descripcio
	from vtadcp
		inner join planctas on planctas.idPlanCta = vtadcp.idPlanCta
	where idVentasC = _idVentasC;
end ;;
